# Generated by manage.py generate_test_cases.
"""Exercise shared placement, time representation, and unique booking origin."""

from datetime import UTC, date, datetime, timedelta
from typing import Any

from django.core.exceptions import ValidationError
from django.db import IntegrityError

from bloomerp.models.communication.calendar import CalendarEvent
from bloomerp.tests.base import (
    BloomerpModelTestCase,
    ExpectedModelException,
    ModelScenario,
)

from .fixtures import CalendarFixtures


class TestCalendarEventModel(CalendarFixtures, BloomerpModelTestCase):
    model = CalendarEvent

    def get_test_scenarios(self) -> list[ModelScenario[CalendarEvent]]:
        """Cover shared calendars and invalid date or booking-origin combinations."""
        scenarios = [
            ModelScenario(
                name="One meeting appears in several inboxes and moves without copies",
                preparation=self.prepare,
                create_args=self.event_args,
                post_create=self.add_placements,
                create_validators=self.has_shared_placements,
                update_args={"title": "Rescheduled planning"},
                update_validators=self.move_placement,
            ),
            ModelScenario(
                name="Timed events round-trip as UTC instants",
                create_args=self.event_args,
                create_validators=self.is_utc_instant,
            ),
            ModelScenario(
                name="All-day date ranges retain their exclusive end",
                create_args=self.all_day_args,
                create_validators=self.is_date_range,
            ),
            ModelScenario(
                name="Submission creates at most one event",
                preparation=self.prepare,
                create_args=self.duplicate_submission_args,
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            ),
            ModelScenario(
                name="Database rejects invalid ranges even in a bulk insert",
                create_operation=self.bulk_invalid_event,
                expected_exceptions=[ExpectedModelException("create", IntegrityError)],
            ),
        ]
        invalid_cases = [
            ("Missing timed instants", {"start": None, "end": None}),
            ("Reversed timed interval", {"end": datetime(2026, 1, 1, tzinfo=UTC)}),
            ("Empty timed interval", {"end": self.event_args()["start"]}),
            ("Missing event timezone", {"event_timezone": None}),
            ("Unknown timezone", {"event_timezone": "Invalid/Timezone"}),
            (
                "Naive instant",
                {"start": self.event_args()["start"].replace(tzinfo=None)},
            ),
            ("Mixed date and time representation", {"start_date": date(2026, 10, 15)}),
            ("All-day event with timed fields", {"all_day": True}),
        ]
        for name, overrides in invalid_cases:
            scenarios.append(
                ModelScenario(
                    name=name,
                    create_args=self.event_args(**overrides),
                    expected_exceptions=[
                        ExpectedModelException("create", ValidationError)
                    ],
                )
            )
        scenarios.append(
            ModelScenario(
                name="All-day end must be after start",
                create_args=self.all_day_args(end_date=date(2026, 10, 15)),
                expected_exceptions=[ExpectedModelException("create", ValidationError)],
            )
        )
        return scenarios

    def all_day_args(self, **overrides: Any) -> dict[str, Any]:
        """Build date-only event arguments with an exclusive end date."""
        return self.event_args(
            start=None,
            end=None,
            event_timezone=None,
            all_day=True,
            start_date=date(2026, 10, 15),
            **{"end_date": date(2026, 10, 17), **overrides},
        )

    def add_placements(self, event: CalendarEvent) -> None:
        """Place a single externally organized meeting in two calendars."""
        event.inboxes.add(self.inbox, self.team_inbox)

    def has_shared_placements(self, event: CalendarEvent) -> bool:
        """Confirm placement does not manufacture attendees or organizer authority."""
        return (
            event.inboxes.count() == 2
            and not event.participants.exists()
            and event.organizing_inbox_id is None
            and self.inbox.calendar_events.get().pk
            == self.team_inbox.calendar_events.get().pk
        )

    def move_placement(self, event: CalendarEvent) -> bool:
        """Verify both calendars see edits and removing one placement keeps the event."""
        same_title = (
            self.team_inbox.calendar_events.get().title == "Rescheduled planning"
        )
        event.inboxes.remove(self.inbox)
        return (
            same_title
            and event.inboxes.count() == 1
            and CalendarEvent.objects.filter(pk=event.pk).exists()
        )

    def is_utc_instant(self, event: CalendarEvent) -> bool:
        """Confirm timezone conversion preserves the scheduled instant."""
        return event.start == datetime(
            2026, 10, 15, 12, tzinfo=UTC
        ) and event.start.utcoffset() == timedelta(0)

    def is_date_range(self, event: CalendarEvent) -> bool:
        """Confirm all-day dates are not represented by shifted UTC midnights."""
        return (
            event.start is None
            and event.end is None
            and event.end_date == date(2026, 10, 17)
        )

    def duplicate_submission_args(self) -> dict[str, Any]:
        """Attempt to reuse a submission already referenced by another event."""
        CalendarEvent.objects.create(
            **self.event_args(calendar_booking_submission=self.submission)
        )
        return self.event_args(calendar_booking_submission=self.submission)

    def bulk_invalid_event(self) -> CalendarEvent:
        """Bypass save validation to exercise the database time-range constraint."""
        event = CalendarEvent(**self.event_args(start=None, end=None))
        CalendarEvent.objects.bulk_create([event])
        return event
